import sys
import math

def get_divisors(n):
    """Return a sorted list of all divisors of n."""
    divisors = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

a, b = map(int, sys.stdin.readline().split())
queries = int(sys.stdin.readline())

# Find all common divisors of a and b
common_gcd = math.gcd(a, b)
divisors = get_divisors(common_gcd)

for _ in range(queries):
    line = sys.stdin.readline().strip()
    if not line:
        continue
    low, high = map(int, line.split())

    # Try to find the greatest divisor in the range [low, high]
    result = -1
    for d in reversed(divisors):
        if low <= d <= high:
            result = d
            break

    print(result)
"}

