# Read 3x3 grid of presses
presses = []
for _ in range(3):
    row = list(map(int, input().split()))
    presses.append(row)

# Calculate final state for each light
for i in range(3):
    for j in range(3):
        # Count number of times light (i,j) is toggled
        count = presses[i][j]  # self
        # Check adjacent lights
        if i > 0:
            count += presses[i-1][j]
        if i < 2:
            count += presses[i+1][j]
        if j > 0:
            count += presses[i][j-1]
        if j < 2:
            count += presses[i][j+1]

        # Final state: 1 if even toggles, 0 if odd
        if count % 2 == 0:
            print('1', end='')
        else:
            print('0', end='')
    print()
"}

