def count_div2(n):
    count = 0
    while n % 2 == 0:
        count += 1
        n //= 2
    return count

n_test_cases = int(input())
for _ in range(n_test_cases):
    w, h, n = map(int, input().split())

    count_w = count_div2(w)
    count_h = count_div2(h)

    max_sheets = 1 << (count_w + count_h)  # 2^(count_w + count_h)

    if max_sheets >= n:
        print("YES")
    else:
        print("NO")
"}

