{"code": "
n, k = map(int, input().split())

if k > n:
    if k - n >= 2:
        print("No")
    else:
        # k - n == 1, so only one i > n with remainder = n
        seen = set()
        distinct = True

        # Check remainders from 1 to n
        for i in range(1, n + 1):
            rem = n % i
            if rem in seen:
                distinct = False
                break
            seen.add(rem)

        # Check the last value i = n+1
        if n in seen:
            distinct = False

        print("Yes" if distinct else "No")
else:
    # k <= n, just check all values from 1 to k
    seen = set()
    distinct = True

    for i in range(1, k + 1):
        rem = n % i
        if rem in seen:
            distinct = False
            break
        seen.add(rem)

    print("Yes" if distinct else "No")
"}

