n = int(input())
for _ in range(n):
    n2 = int(input())
    s = input().strip()

    moves = 0

    # The first character must be '('
    if s[0] == ')':
        moves += 1

    # At each position, count of '(' must be >= count of ')' after moving
    balance = 0

    for i in range(n2):
        if s[i] == '(':
            balance += 1
        else:
            balance -= 1

        # If balance < 0 at any point, we need to fix it
        if balance < 0:
            # Move this ')' to the beginning
            moves += 1
            balance += 1  # After moving, balance becomes 0

    print(moves)
"}

