def solve():
    # Read input
    N = int(input())
    grid = []
    for i in range(N):
        row = list(map(int, input().split()))
        grid.append(row)

    # Use dynamic programming to find maximum path sums
    # First, going from (0,0) to (N-1,N-1)
    # We can only move right or down
    dp1 = [[0]*N for _ in range(N)]
    dp1[0][0] = grid[0][0]

    # Fill dp1 for right/down movement
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i > 0:
                dp1[i][j] = max(dp1[i][j], dp1[i-1][j])
            if j > 0:
                dp1[i][j] = max(dp1[i][j], dp1[i][j-1])
            dp1[i][j] += grid[i][j]

    # Second, returning from (N-1,N-1) to (0,0)
    # We can only move left or up
    dp2 = [[0]*N for _ in range(N)]
    dp2[N-1][N-1] = grid[N-1][N-1]

    # Fill dp2 for left/up movement
    for i in range(N-1, -1, -1):
        for j in range(N-1, -1, -1):
            if i == N-1 and j == N-1:
                continue
            if i < N-1:
                dp2[i][j] = max(dp2[i][j], dp2[i+1][j])
            if j < N-1:
                dp2[i][j] = max(dp2[i][j], dp2[i][j+1])
            dp2[i][j] += grid[i][j]

    # The answer is dp1[N-1][N-1] + dp2[N-1][N-1] - grid[N-1][N-1]
    # (since we counted bottom-right cell twice)
    print(dp1[N-1][N-1] + dp2[N-1][N-1] - grid[N-1][N-1])

solve()
