import sys

def solve() -> None:
    s = sys.stdin.readline().strip()

    # Count characters
    a = s.count('a')
    b = s.count('b')
    c = s.count('c')

    # Check if at least one 'a' and one 'b'
    if a == 0 or b == 0:
        print("NO")
        return

    # Check if all 'a's come before all 'b's
    a_index = s.index('a')
    b_index = s.rindex('b')
    if not (a_index <= b_index):
        print("NO")
        return

    # Check if all 'b's come before all 'c's
    if b_index >= 0 and c > 0:
        b_before_c = s.index('b') <= s.index('c')
        b_all_before_c = True

        # Check all 'b's are before all 'c's
        for i in range(len(s)):
            if s[i] == 'b':
                if s[i] == 'b':
                    if s[i] == 'c':
                        b_all_before_c = False
                        break

        # Actually, simpler: check if all 'b's index <= all 'c's index
        for i in range(len(s)):
            if s[i] == 'b':
                if any(s[j] == 'c' and j < i for j in range(len(s))):
                    b_all_before_c = False
                    break

        if not b_all_before_c:
            print("NO")
            return

    # Check if c equals a or b
    if c == a or c == b:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
