def is_valid_expression(s):
    """Check if a string s is a valid arithmetic expression"""

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.end = len(s)

        def current(self):
            if self.pos >= self.end:
                return None
            return self.s[self.pos]

        def consume(self):
            self.pos += 1

        def parse_E(self):
            # E = T | E '+' T
            result = self.parse_T()
            while self.current() == '+':
                self.consume()
                right = self.parse_T()
                result = (result, '+', right)
            return result

        def parse_T(self):
            # T = F | T '*' F
            result = self.parse_F()
            while self.current() == '*':
                self.consume()
                right = self.parse_F()
                result = (result, '*', right)
            return result

        def parse_F(self):
            # F = digit | '(' E ')'
            if self.current() == '(':
                self.consume()
                result = self.parse_E()
                if self.current() == ')':
                    self.consume()
                    return result
                else:
                    return None
            elif self.current() is not None and self.current() in '123456789':
                digit = int(self.current())
                self.consume()
                return digit
            else:
                return None

    p = Parser(s)
    return p.parse_E() is not None


def evaluate_expression(s):
    """Evaluate the expression s"""

    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.end = len(s)

        def current(self):
            if self.pos >= self.end:
                return None
            return self.s[self.pos]

        def consume(self):
            self.pos += 1

        def parse_E(self):
            left = self.parse_T()
            while self.current() == '+':
                self.consume()
                right = self.parse_T()
                left = left + right
            return left

        def parse_T(self):
            left = self.parse_F()
            while self.current() == '*':
                self.consume()
                right = self.parse_F()
                left = left * right
            return left

        def parse_F(self):
            if self.current() == '(':
                self.consume()
                value = self.parse_E()
                if self.current() == ')':
                    self.consume()
                    return value
                else:
                    return None
            elif self.current() is not None and self.current() in '123456789':
                digit = int(self.current())
                self.consume()
                return digit
            else:
                return None

    p = Parser(s)
    return p.parse_E()


def solve():
    import sys
    input = sys.stdin.read().splitlines()

    index = 0
    while index < len(input):
        line = input[index].strip()
        if not line:
            index += 1
            continue

        if line == '0':
            break

        n = int(line)
        index += 1
        s = input[index].strip()
        index += 1

        # Count valid substrings that evaluate to n
        count = 0
        length = len(s)

        for i in range(length):
            for j in range(i + 1, length + 1):
                substr = s[i:j]
                if is_valid_expression(substr):
                    value = evaluate_expression(substr)
                    if value == n:
                        count += 1

        print(count)

if __name__ == '__main__':
    solve()

