        grid = []
        for _ in range(n):
            grid.append(list(map(int, sys.stdin.readline().split())))

        max_count = 0

        # DFS to find longest path
        def dfs(row, col, visited):
            visited[row * m + col] = True
            count = 1

            for drow, dcol in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                new_row = row + drow
                new_col = col + dcol

                if 0 <= new_row < n and 0 <= new_col < m and grid[new_row][new_col] == 1 and not visited[new_row * m + new_col]:
                    count = max(count, dfs(new_row, new_col, visited) + 1)

            visited[row * m + col] = False
            return count

        # Find all cells with thin ice
        start_cells = []
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    start_cells.append((i, j))

        for start_row, start_col in start_cells:
            visited = [False] * (n * m)
            count = dfs(start_row, start_col, visited)
            max_count = max(max_count, count)

