import sys

def count_divisions_by_two(n):
    """Count how many times n can be divided by 2"""
    if n == 0:
        return 0
    count = 0
    while n % 2 == 0:
        count += 1
        n //= 2
    return count

def solve():
    t = int(sys.stdin.readline())
    results = []
    for _ in range(t):
        w, h, n = map(int, sys.stdin.readline().split())
        w_divisions = count_divisions_by_two(w)
        h_divisions = count_divisions_by_two(h)
        max_sheets = 2 ** (w_divisions + h_divisions)
        if max_sheets >= n:
            results.append("YES")
        else:
            results.append("NO")
    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

