    # Find when the barn empties
    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        current = n
        for i in range(1, mid + 1):
            current = min(current + m, n)
            current -= i
            if current <= 0:
                break
        if current <= 0:
            right = mid
        else:
            left = mid + 1
    print(left)
