    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u, w = map(int, sys.stdin.readline().split())
        graph[u].append(w)
        graph[w].append(u)

    # Kruskal's algorithm (minimum spanning tree)
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        parent[find(x)] = find(y)

    # Sort parts by value ascending
    # We'll add edges in ascending order
    edges = []
    for i in range(1, n + 1):
        for neighbor in graph[i]:
            if i < neighbor:
                edges.append((v[i - 1], v[neighbor - 1], i, neighbor))

    # Sort edges by minimum value
    edges.sort()

    # Kruskal's algorithm
    for value_i, value_j, u, v in edges:
        if find(u) != find(v):
            union(u, v)

    # Calculate total cost
    total_cost = 0

    for i in range(1, n + 1):
        # Cost for part i = value of i multiplied by (degree - number of edges in MST)
        degree = len(graph[i])
        count = 0
        for neighbor in graph[i]:
            if find(neighbor) == find(i):
                count += 1
        total_cost += v[i - 1] * (degree - count)

    print(total_cost)

