def matches(pattern, address):
    """Check if pattern matches address with ? as wildcard."""
    if len(pattern) != len(address):
        return False
    for p_char, a_char in zip(pattern, address):
        if p_char == '?':
            continue
        if p_char != a_char:
            return False
    return True

def solve():
    while True:
        line = input().strip()
        while line == '':
            line = input().strip()
        n, m = map(int, line.split())

        if n == 0 and m == 0:
            break

        rules = []

        for i in range(n):
            rule_line = input().strip()
            while rule_line == '':
                rule_line = input().strip()
            parts = rule_line.split()
            action = parts[0]
            src_pattern = parts[1]
            dst_pattern = parts[2]
            rules.append((action, src_pattern, dst_pattern))

        legal_packets = []

        for _ in range(m):
            packet_line = input().strip()
            while packet_line == '':
                packet_line = input().strip()
            parts = packet_line.split()
            src_addr = parts[0]
            dst_addr = parts[1]
            message = parts[2]

            legal = False

            # Check all rules from last to first (highest priority first)
            for action, src_pat, dst_pat in reversed(rules):
                if matches(src_pat, src_addr) and matches(dst_pat, dst_addr):
                    if action == 'permit':
                        legal = True
                        break
                    else:
                        # If it matches a deny rule, it's not legal (unless a permit rule matches later)
                        legal = False

            if legal:
                legal_packets.append((src_addr, dst_addr, message))

        print(len(legal_packets))
        for packet in legal_packets:
            print(f"{packet[0]} {packet[1]} {packet[2]}")

if __name__ == '__main__':
    solve()
