import sys

def count_leading_dots(line):
    """Count the number of leading '.' characters in the line"""
    count = 0
    for c in line:
        if c == '.':
            count += 1
        else:
            break
    return count

def format_tree(lines):
    """Format a list of lines representing a thread tree"""
    output = []
    for i, line in enumerate(lines):
        depth = count_leading_dots(line)

        # First line (root) always starts with "+ "
        if i == 0:
            output.append(f"+ {line}")
        else:
            prev_depth = count_leading_dots(lines[i-1])

            # For each level deeper than previous depth, add a "|"
            if depth > prev_depth:
                output_line = "+"
                for _ in range(depth - prev_depth):
                    output_line += "|"
            else:
                # For siblings at the same depth, use a space after "+"
                output_line = " "

            # Add the line content
            output_line += f" {line}"
            output.append(output_line)
    return output

def main():
    lines = []
    while True:
        line = input().strip()
        if line == "":
            continue

        # Check if we've reached the end
        if line == "0":
            if lines:  # If we have content before 0, we're done
                break
            continue

        n = int(line)

        if n == 0:
            if lines:
                # If we have content and then 0, we're done
                break
            continue

        # Read the n lines
        for _ in range(n):
            s = input().strip()
            if s:
                lines.append(s)

        # Format and print
        for formatted_line in format_tree(lines):
            print(formatted_line)

        # Reset lines for next dataset
        lines.clear()

if __name__ == "__main__":
    main()
