n = int(input())

# Find the head
head = -1
for x in range(1, n + 1):
    for y in range(1, n + 1):
        print(f"? {x} {y} {x} {y}")
        sys.stdout.flush()
        line = sys.stdin.readline()
        if line.strip():
            res = int(line.strip())
            if res == 1:
                head = (x, y)
                break
    if head != -1:
        break

if head == -1:
    print("! 1 1 1 1")
else:
    x1, y1 = head
    x2, y2 = -1, -1

    # Binary search for the other endpoint (tail)
    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        print(f"? {x1} {y1} {mid} {y2}")
        sys.stdout.flush()
        line = sys.stdin.readline()
        if line.strip():
            res = int(line.strip())
        # If we get 1, the other endpoint is at this row or below
        if res == 1:
            left = mid + 1
        else:
            right = mid

    x2 = left

    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        print(f"? {x1} {y1} {x2} {mid}")
        sys.stdout.flush()
        line = sys.stdin.readline()
        if line.strip():
            res = int(line.strip())
        if res == 1:
            left = mid + 1
        else:
            right = mid

    y2 = left

    print(f"! {x1} {y1} {x2} {y2}")
