def solve():
    n = int(input())
    l = input().strip()
    r = input().strip()

    # Count specific characters (not '?')
    from collections import defaultdict

    l_count = defaultdict(int)
    r_count = defaultdict(int)

    # Count the '?'
    l_q = 0
    r_q = 0

    # First pass: count characters and count '?'
    for i in range(n):
        lc = l[i]
        rc = r[i]

        if lc != '?':
            l_count[lc] += 1
        else:
            l_q += 1

        if rc != '?':
            r_count[rc] += 1
        else:
            r_q += 1

    # Second pass: pair up specific characters
    pairs = []

    # Create a list of characters for each string
    chars_l = []
    chars_r = []

    for i in range(n):
        if l[i] == '?':
            chars_l.append(None)
        else:
            chars_l.append(l[i])

        if r[i] == '?':
            chars_r.append(None)
        else:
            chars_r.append(r[i])

    # Pair up specific characters
    for c in l_count:
        if c in r_count:
            # Pair up min of both
            cnt = min(l_count[c], r_count[c])

            # Find indices with this character
            left_indices = [i + 1 for i, ch in enumerate(chars_l) if ch == c]
            right_indices = [i + 1 for i, ch in enumerate(chars_r) if ch == c]

            # Take the first cnt from each
            for i in range(cnt):
                pairs.append((left_indices[i], right_indices[i]))

    # Now pair '?'
    if l_q > 0:
        # Left has '?'
        if r_q > 0:
            # Pair '?' with '?'
            for i in range(l_q):
                pairs.append((l_q - i, r_q - i))
        else:
            # Pair '?' with remaining specific characters in right
            # Find which specific characters are still available
            for i in range(l_q):
                pairs.append((l_q - i, next((j + 1 for j, ch in enumerate(chars_r) if ch is not None), None)))
    elif r_q > 0:
        # Right has '?'
        if l_q > 0:
            # Pair '?' with '?'
            for i in range(r_q):
                pairs.append((l_q - i, r_q - i))
        else:
            # Pair '?' with remaining specific characters in left
            for i in range(r_q):
                pairs.append((next((j + 1 for j, ch in enumerate(chars_l) if ch is not None), None), r_q - i))

    print(len(pairs))
    for a, b in pairs:
        print(f"{a} {b}")

