def count_original_strings(s):
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        # If we have 'w' or 'm', we need to consider special cases
        if s[i-1] == 'w':
            # 'w' comes from 'uu' in original string
            if i >= 2 and s[i-2] == 'u':
                dp[i] = (dp[i] + dp[i-2]) % MOD
        elif s[i-1] == 'm':
            # 'm' comes from 'nn' in original string
            if i >= 2 and s[i-2] == 'n':
                dp[i] = (dp[i] + dp[i-2]) % MOD
        else:
            # Any other character comes from itself
            dp[i] = dp[i-1]

    return dp[n]

