    dp[0] = 1

    for i in range(1, n + 1):
        # If we see 'w', we need to look at the previous character
        if s[i-1] == 'w':
            if i >= 2 and s[i-2] == 'u':
                dp[i] = dp[i-2]
        elif s[i-1] == 'm':
            if i >= 2 and s[i-2] == 'n':
                dp[i] = dp[i-2]
        else:
