    # Try each possible max count (m) from 0 to n
    for max_count in range(0, n + 1):
        # We can have counts that are either max_count or max_count - 1
        # Try all combinations of which numbers have which counts

        from itertools import combinations

        # Try taking max_count cards of some subset of numbers
        for num_take_m in range(0, 9):
            for num_take_m_minus1 in range(0, 9):
                # Create a list of counts
                c = [0] * 9
                for i in range(1, 9):
                    if num_take_m > 0:
                        if counts[i] >= max_count:
                            c[i] = max_count
                        else:
                            c[i] = 0
                    elif num_take_m_minus1 > 0:
                        if counts[i] >= max_count - 1:
                            c[i] = max_count - 1
                        else:
                            c[i] = 0
                    else:
                        c[i] = 0

                # Check if this configuration is valid
                # - Counts should be either max_count or max_count - 1
                valid = True
                for i in range(1, 9):
                    if c[i] < 0 or c[i] > max_count:
                        valid = False
                        break
                if not valid:
                    continue

                # Check if we can form the subsequence
                # Using a greedy approach: go through the cards and try to form the sequence

                # Keep track of how many of each number we still need
                needed = [0] * 9
                for i in range(1, 9):
                    needed[i] = c[i]

                valid_seq = True
                current_block = []
                for i, card in enumerate(cards):
                    # Try to add this card to the current block
                    # But we need to ensure all occurrences of a number in the block are contiguous

                    # If we already have this number in the block, we need to ensure the block is still valid
                    if needed[card] > 0:
                        needed[card] -= 1
                        current_block.append(card)

                        # If this was the first occurrence of this number in the block, check validity
                        if current_block and current_block[0] != card:
