import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    arr = list(map(int, data[2:2+n]))

    suffix_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        suffix_sum[i] = suffix_sum[i-1] + arr[i-1]

    # dp[i][j]: dict of {last_sum: max_value}
    dp = [[{} for _ in range(k+1)] for _ in range(n+1)]
    dp[0][0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if j == 1:
                # Start first subarray
                for l in range(i):
                    new_sum = suffix_sum[i] - suffix_sum[l]
                    # Allow sum 0 (subarray could be [0])
                    if new_sum == 0 and l != i-1:
                        # Sum zero but subarray is [0] at position i => l = i-1 (sum of single element 0)
                        # Or multiple zeros. But we allow any non-empty subarray, including sum 0.
                        # However, if l = i-1, new_sum = arr[i-1]. If arr[i-1] == 0, new_sum = 0.
                        # Still valid. So we allow sum 0.
                        pass
                    # Actually sum can be 0. We can continue.
                    # But for k=1, we want value = 0, not |0 - new_sum|. But we used transition from dp[0][0][0],
                    # which would give |0 - new_sum|. So we need to handle j=1 specially.
                    # Actually for j=1, we should not add |0 - new_sum|. We can do:
                    # new_sum = ...; new_val = 0 if j == 1 else prev_val + abs(...)
                    # But we can still use transition by setting prev_val = 0 for dp[0][0] and then not adding |...|.
                    # Or we can initialize dp[i][1] with new_val = 0.
                    # Let's just set value = 0 directly.
                    dp[i][j][new_sum] = max(dp[i][j].get(new_sum, -float('inf')), 0)
            else:
                for l in range(i):
                    for prev_sum, prev_val in dp[l][j-1].items():
                        new_sum = suffix_sum[i] - suffix_sum[l]
                        new_val = prev_val + abs(prev_sum - new_sum)
                        dp[i][j][new_sum] = max(dp[i][j].get(new_sum, -float('inf')), new_val)

    ans = -float('inf')
    for i in range(1, n + 1):
        if dp[i][k]:
            ans = max(ans, max(dp[i][k].values()))

    print(ans)

if __name__ == "__main__":
