def square_free_part(n):
    """Return the square-free part of a number."""
    if n == 0:
        return 0

    # Handle negative numbers by taking absolute value
    # Actually, we should preserve sign for -4
    if n < 0:
        n = -n
        sign = -1
    else:
        sign = 1

    # Handle 1 separately
    if n == 1:
        return sign

    result = 1

    # Find the square-free part by removing all squares
    for p in range(2, int(n**0.5) + 1):
        cnt = 0
        while n % p == 0:
            cnt += 1
            n //= p
        if cnt % 2 == 1:
            # Odd power means we keep this prime
            result *= p

    # If we still have n > 1, it means we had an odd power of n itself
    if n > 1:
        result *= n

    return sign * result

n = int(input())
A = list(map(int, input().split()))

# Compute square-free parts
square_free = []
for num in A:
    sq = square_free_part(num)
    square_free.append(sq)

# Count how many subarrays have exactly k distinct square-free parts
output = [0] * n

# Brute force all subarrays
for length in range(1, n + 1):
    for start in range(n - length + 1):
        seen = set()
        for i in range(start, start + length):
            seen.add(square_free[i])
        distinct = len(seen)
        if distinct <= n:
            output[distinct - 1] += 1

print(" ".join(map(str, output)))
"}

