import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    # Count each status
    count = [0] * 3  # [F, A, I]
    for ch in s:
        idx = ord(ch) - ord('F')
        if 0 <= idx < 3:
            count[idx] += 1

    # Count cows that can show hands
    result = 0
    for ch in s:
        idx = ord(ch) - ord('F')
        if 0 <= idx < 3:
            if count[idx] == 0:
                continue
            # Check if all other cows are F or A
            if (count[0] + count[1] - (1 if idx == 1 else 0)) == (n - 1):
                result += 1

    print(result)

if __name__ == "__main__":
    solve()
