            count[2] += 1

    # Count cows that can show hands
    result = 0
    for ch in s:
        if ch == 'F':
            continue
        # Calculate counts of A and F among all others
        a_other = count[1] - (1 if ch == 'A' else 0)
        f_other = count[0]

        # Check if all others are A or F
        if a_other + f_other == n - 1:
            result += 1

    print(result)

