def find_perfect_number(k):
    # Start with two-digit numbers
    for first in range(1, 10):
        second = 10 - first
        if second >= 0 and second <= 9:
            yield first * 10 + second

    # Start with three-digit numbers (1 followed by other digits)
    for second in range(0, 10):
        third = 9 - second
        if third >= 0 and third <= 9:
            yield 100 + second * 10 + third

    # And so on...
    # But wait, we need a general approach

    # We can think of it as: find numbers where digits sum to 10
    # We can generate numbers digit by digit

    from collections import deque

    queue = deque()
    queue.append("")

    while True:
        num_str = queue.popleft()
        if num_str:
            digits = [int(c) for c in num_str]
            if sum(digits) == 10:
                yield int(num_str)

        # Add next digit (0-9) to the number
        for next_digit in range(10):
            queue.append(num_str + str(next_digit))

    # But we need to stop after k numbers

k = int(input())

# Generate perfect numbers in increasing order
perfect_numbers = []
queue = deque()
queue.append("")

while len(perfect_numbers) < k:
    num_str = queue.popleft()
    if num_str:
        digits = [int(c) for c in num_str]
        if sum(digits) == 10:
            perfect_numbers.append(int(num_str))

    # Add next digit (0-9) to the number
    for next_digit in range(10):
        queue.append(num_str + str(next_digit))

print(perfect_numbers[-1])
