    for _ in range(T):
        N = int(input())
        min_diff = N  # maximum possible difference is N itself (1 x N)

        # Iterate from 1 to sqrt(N)
        for i in range(1, int(math.isqrt(N)) + 1):
            if N % i == 0:
                # i is a divisor, N//i is the corresponding factor
                min_diff = min(min_diff, abs(N // i - i))

        print(min_diff)

solve()
