    for j in range(3):
        presses = grid[i][j]
        # If pressed odd number of times, toggle the light and its neighbors
        if presses % 2 == 1:
            # Toggle current light
            light_grid[i][j] ^= 1  # XOR with 1 toggles the bit

            # Toggle top neighbor
            if i > 0:
                light_grid[i-1][j] ^= 1
            # Toggle bottom neighbor
            if i < 2:
                light_grid[i+1][j] ^= 1
            # Toggle left neighbor
            if j > 0:
                light_grid[i][j-1] ^= 1
            # Toggle right neighbor
            if j < 2:
                light_grid[i][j+1] ^= 1

# Print result
for row in light_grid:
    print(''.join(map(str, row)))
