for _ in range(3):
    grid.append(list(map(int, input().split())))

# Create result grid (start with all 1s)
result = [[1 for _ in range(3)] for _ in range(3)]

# Press each light the given number of times
# Since pressing even times cancels out, we just need to count modulo 2
for i in range(3):
    for j in range(3):
        presses = grid[i][j]
        # Press the light presses times
        for _ in range(presses % 2):
            # Toggle the light and its adjacent lights
            result[i][j] ^= 1
            if i > 0:
