def match_pattern(pattern, value):
    """Check if value matches the pattern where '?' matches any digit."""
    if len(pattern) != 8 or len(value) != 8:
        return False

    for p, v in zip(pattern, value):
        if p == '?':
            continue
        elif p == v:
            continue
        else:
            return False
    return True


def solve():
    while True:
        # Read n and m
        line = input()
        while line.strip() == '':
            line = input()

        n, m = map(int, line.strip().split())

        if n == 0 and m == 0:
            break

        rules = []
        for _ in range(n):
            rule = input()
            while rule.strip() == '':
                rule = input()
            parts = rule.strip().split()
            rule_type = parts[0]
            src_pattern = parts[1]
            dest_pattern = parts[2]
            rules.append((rule_type, src_pattern, dest_pattern))

        legal_packets = []
        for _ in range(m):
            packet = input()
            while packet.strip() == '':
                packet = input()
            src, dest, message = packet.strip().split()

            is_legal = False
            for rule in rules:
                rule_type, src_pat, dest_pat = rule
                if rule_type == 'permit' and match_pattern(src_pat, src) and match_pattern(dest_pat, dest):
                    is_legal = True
                elif rule_type == 'deny' and match_pattern(src_pat, src) and match_pattern(dest_pat, dest):
                    is_legal = False

            if is_legal:
                legal_packets.append((src, dest, message))

        # Output results
        print(len(legal_packets))
        for packet in legal_packets:
            print(f"{packet[0]} {packet[1]} {packet[2]}")

if __name__ == "__main__":
    solve()
"}

