def is_valid(expr):
    """Check if the expression conforms to the grammar"""
    if not expr:
        return False
    if expr[0] == '(':
        return expr[-1] == ')' and is_valid(expr[1:-1])
    if expr[-1] == '(':
        return False  # Shouldn't end with '('
    if expr[-1] == ')':
        return False  # Shouldn't end with ')'

    if expr[0] in '+*':
        return False  # Shouldn't start with operator

    # Check for single digit
    if len(expr) == 1:
        return expr.isdigit()

    # Try to find operators
    for i in range(1, len(expr)):
        if expr[i] == '+' or expr[i] == '*':
            if is_valid(expr[:i]) and is_valid(expr[i+1:]):
                return True

    # Try parentheses
    for i in range(1, len(expr)-1):
        if expr[i] == ')' and expr[-1] == ')':
            return False
        if expr[i] == '(':
            if expr[0] == '(':
                continue
            if expr[-1] == '(':
                continue
            j = i
            while j < len(expr) and expr[j] != ')':
                j += 1
            if j < len(expr) and expr[j] == ')' and is_valid(expr[0:i]) and is_valid(expr[i+1:j]) and is_valid(expr[j+1:]):
                return True

    return False

def evaluate(expr):
    """Evaluate the expression"""
    stack = []
    i = 0
    while i < len(expr):
        if expr[i] == '(':
            stack.append('(')
            i += 1
        elif expr[i] == ')':
            if stack and stack[-1] == '(':
                stack.pop()
                i += 1
            else:
                return None
        elif expr[i] in '+*':
            stack.append(expr[i])
            i += 1
        else:
            # Parse number
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            number = int(expr[i:j])
            i = j

            # Evaluate current stack
            while stack and stack[-1] in ('+', '*') and (len(stack) < 2 or stack[-2] != '('):
                op = stack.pop()
                right = number
                number = stack.pop()
                if op == '+':
                    number += right
                else:
                    number *= right
                stack.append(number)
            stack.append(number)

    if stack:
        return None

    if isinstance(stack[0], int):
        return stack[0]
    return None


def solve():
