def find_largest_divisor_in_range(g, low, high):
    """Find the largest divisor of g that lies within [low, high]"""
    if g < low:
        # Check if there's any divisor in range
        # Start from the largest possible divisor less than g
        for divisor in range(g // 2, 0, -1):
            if g % divisor == 0 and low <= divisor <= high:
                return divisor
        return -1
    elif g > high:
        # Check if there's any divisor in range that's less than g
        for divisor in range(g // 2, 0, -1):
            if g % divisor == 0 and low <= divisor <= high:
                return divisor
        return -1
    else:
        # g itself is in range
        return g

# Process queries
