def solve():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    arr = list(map(int, input[2:2+n]))

    # precompute prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + arr[i]

    # dp[i][j]: dictionary mapping last subarray sum to best value
    # dp[i][j][s] = best value when we end at position i with j subarrays, last subarray sum s
    dp = [{} for _ in range(n + 1)]

    # base case: j = 1
    for i in range(1, n + 1):
        # try all subarrays ending at i
        for l in range(1, i + 1):
            s = prefix[i] - prefix[l - 1]
            if s not in dp[i] or dp[i][s] < 0:
                dp[i][s] = 0  # no previous subarray, so value is 0

    for j in range(2, k + 1):
        # We need j subarrays
        for i in range(j, n + 1):  # at least j elements needed
            # Try all possible previous positions m where j-1 subarrays could end
            for m in range(j - 1, i):
                if not dp[m]:
                    continue
                # dp[m][j-1] has all possible previous subarray sums at position m
                for s_prev, val_prev in dp[m].items():
                    # Try all subarrays starting at m+1 and ending at i
                    for l in range(m + 1, i + 1):
                        s_current = prefix[i] - prefix[l - 1]
                        # Add the absolute difference with the previous subarray sum
                        new_val = val_prev + abs(s_prev - s_current)
                        if s_current not in dp[i] or dp[i][s_current] < new_val:
                            dp[i][s_current] = new_val

    # Find the maximum value for all i and k subarrays
    result = 0
    for s, val in dp[n].items():
        result = max(result, val)
    print(result)

if __name__ == "__main__":
    solve()
