def bfs(grid, m, n, start_row, start_col):

    # Check if start cell has thin ice
    if grid[start_row][start_col] != 1:
        return 0

    # Create visited matrix
    visited = [[False for _ in range(m)] for _ in range(n)]
    queue = [(start_row, start_col, 1)]  # (row, col, count)
    visited[start_row][start_col] = True

    max_count = 1

    while queue:
        row, col, count = queue.pop(0)

        # Check all four directions
        for drow, dcol in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row = row + drow
            new_col = col + dcol

            # Check bounds and thin ice
            if 0 <= new_row < n and 0 <= new_col < m:
                if not visited[new_row][new_col] and grid[new_row][new_col] == 1:
                    visited[new_row][new_col] = True
                    queue.append((new_row, new_col, count + 1))
                    max_count = max(max_count, count + 1)

