import sys

def encrypt(s):
    output = []
    current = 0
    for ch in s:
        target = ord(ch) - ord('a')
        if target >= current:
            cw = target - current
            ac = 26 - cw
        else:
            cw = target - current + 26
            ac = current - target
        if cw < ac:
            output.append(cw)
        elif ac < cw:
            output.append(-ac)
        else:
            output.append(cw)
        current = (current + output[-1]) % 26
    return ' '.join(map(str, output))

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    T = int(data[0])
    for i in range(1, T + 1):
        s = data[i].strip()
        print(encrypt(s))

if __name__ == '__main__':
    main()
