def solve():
    n = int(input())
    cards = list(map(int, input().split()))

    max_len = 0

    # Try all possible count configurations
    # Let k be the base count for most numbers
    for k in range(0, n+1):

        # Try all subsets for numbers with count k+1
        for plus in range(1, 1 << 8):

            # Try all subsets for numbers with count k-1
            for minus in range(1, 1 << 8):

                # Build counts array
                counts = [k] * 8

                # Add 1 for numbers in plus set
                for i in range(8):
                    if (plus >> i) & 1:
                        counts[i] += 1

                # Subtract 1 for numbers in minus set
                for i in range(8):
                    if (minus >> i) & 1:
                        counts[i] -= 1

                # Check if this configuration is valid
                max_count = max(counts)
                min_count = min(counts)
                if abs(max_count - min_count) > 1:
                    continue

                # Also check that we have at least one number with count > 0
                if max_count == 0:
                    continue

                # Try to find the longest subsequence with these counts
                seq = []
                current_count = [0] * 8
                for card in cards:
                    if counts[card-1] > 0:
                        if current_count[card-1] < counts[card-1]:
                            seq.append(card)
                            current_count[card-1] += 1

                if len(seq) == sum(counts) and len(seq) > max_len:
