import sys

def is_valid(word):
    endings = {
        'lios': 'adj_m',
        'liala': 'adj_f',
        'etr': 'noun_m',
        'etra': 'noun_f',
        'initis': 'verb_m',
        'inites': 'verb_f'
    }
    suffix = word[-len(suffix):] if word.endswith(suffix) else None
    return suffix, endings[suffix]

words = sys.stdin.read().strip().split()

# Check all words are valid
valid = True
phrases = []
for word in words:
    for suffix in endings:
        if word.endswith(suffix):
            phrase = (word, suffix, endings[suffix])
            phrases.append(phrase)
            break
    else:
        valid = False
        break

if not valid:
    print("NO")
else:
    # Check order and gender
    n = len(words)
    if n == 1:
        print("YES")
    else:
        # Find noun
        noun_index = None
        noun_gender = None
        adj_count = 0
        verb_count = 0
        for i, (word, suffix, part_of_speech) in enumerate(phrases):
            if part_of_speech == 'noun_m':
                noun_index = i
                noun_gender = 'm'
                break
            elif part_of_speech == 'noun_f':
                noun_index = i
                noun_gender = 'f'
                break
        else:
            # No noun
            print("NO")
            sys.exit()

        # Check noun at correct position
        if noun_index == 0:
            # noun at start
            pass
        else:
            # check before noun all adjectives
            for i in range(noun_index):
                if phrases[i][2] not in ('adj_m', 'adj_f'):
                    print("NO")
                    sys.exit()

        # Check after noun all verbs
        for i in range(noun_index + 1, n):
            if phrases[i][2] != 'verb_m' and phrases[i][2] != 'verb_f':
                print("NO")
                sys.exit()

        # Check all have same gender
        first_gender = phrases[0][2].split('_')[-1]
        for i in range(1, n):
            if phrases[i][2].split('_')[-1] != first_gender:
                print("NO")
                sys.exit()

        print("YES")
