from collections import defaultdict

def solve():
    n, m = map(int, input().split())
    node_values = list(map(int, input().split()))

    # Build adjacency list with edge values
    edges = [[] for _ in range(n)]
    for _ in range(m):
        a, b, c = map(int, input().split())
        a -= 1  # Convert to 0-indexed
        b -= 1
        edges[a].append((b, c))
        edges[b].append((a, c))

    max_density = -float('inf')

    # Try all possible non-empty subsets of nodes
    for k in range(1, n+1):
        # Try all combinations of k nodes
        for subset in combinations(range(n), k):
            # Check if this subset forms a connected subgraph
            # Using BFS to check connectivity
            included = set(subset)
            start = subset[0]
            visited = set([start])
            queue = [start]

            while queue:
                current = queue.pop(0)
                for neighbor, _ in edges[current]:
                    if neighbor in included and neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)

            if visited == included:
                # It's connected, now calculate density
                sum_nodes = sum(node_values[i] for i in subset)
                sum_edges = 0

                # Count edges between nodes in the subset (be careful about double-counting)
                # We can do this by iterating through all edges and checking if both endpoints are in the subset
                for a in range(n):
                    if a not in subset:
                        continue
                    for neighbor, value in edges[a]:
                        if neighbor in subset:
                            sum_edges += value

                if sum_edges > 0:
                    density = sum_nodes / sum_edges
                    if density > max_density:
                        max_density = density

    return max_density

print(solve())
