{"code": "
import sys

n = int(sys.stdin.readline())

# Find a cell that is definitely occupied
def query(x1, y1, x2, y2):
    print(f"? {x1} {y1} {x2} {y2}")
    sys.stdout.flush()
    answer = int(sys.stdin.readline())
    return answer

def find_occupied_cell():
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            ans = query(x, y, x, y)
            if ans > 0:
                return (x, y)
    return None

occupied_cell = find_occupied_cell()
if occupied_cell is None:
    print("! 1 1 1 1")
    sys.stdout.flush()
    return

x, y = occupied_cell

# Trace the path to find head and tail
head = tail = occupied_cell

# Check if head is at (1, 1)
# If head is at (1, 1), it should have a count of 1
ans = query(x, y, x, y)
if ans == 1:
    head = occupied_cell
else:
    # Head might be at (x, y+1), (x+1, y), (x-1, y), or (x, y-1)
    for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
        nx, ny = x + dx, y + dy
        if 1 <= nx <= n and 1 <= ny <= n:
            ans = query(nx, ny, nx, ny)
            if ans > 0:
                head = (nx, ny)
                break

# After finding head, trace to find tail
while True:
    # Check if head is at (1, 1)
    if head == (1, 1):
