import heapq

def solve():
    n, m = map(int, input().split())
    islands = list(map(int, input().split()))
    g, r = map(int, input().split())

    islands.sort()

    # Check if n is present
    if n not in islands:
        print(-1)
        return

    # We need to consider states: (position, time_mod, last_move_dir)
    pq = []
    heapq.heappush(pq, (0, 0, 0, None))  # (time, position, time_mod, last_move_dir)

    dist = {}

    while pq:
        time, pos, time_mod, last_move_dir = heapq.heappop(pq)

        state = (pos, time_mod, last_move_dir)
        if state in dist and dist[state] <= time:
            continue
        dist[state] = time

        if pos == n:
            # Reached the end
            return time

        # Calculate next state
        next_time = time + 1
        next_time_mod = (time + 1) % (g + r)
        next_pos = pos
        next_last_move_dir = last_move_dir

        if time_mod < g:
            # Green light, we can move
            if pos > 0:
                # Move left
                new_pos = pos - 1
                if last_move_dir != -1 or new_pos == pos:
                    if next_time_mod < g:
                        if new_pos == pos:
                            # Stay still at a safety island
                            next_last_move_dir = last_move_dir
                            heapq.heappush(pq, (next_time, new_pos, next_time_mod, next_last_move_dir))
                        else:
                            # Move to a non-safety island
                            heapq.heappush(pq, (next_time, new_pos, next_time_mod, -1))
            if pos < n:
                # Move right
                new_pos = pos + 1
                if last_move_dir != 1 or new_pos == pos:
                    if next_time_mod < g:
                        if new_pos == pos:
                            next_last_move_dir = last_move_dir
                            heapq.heappush(pq, (next_time, new_pos, next_time_mod, next_last_move_dir))
                        else:
                            heapq.heappush(pq, (next_time, new_pos, next_time_mod, 1))
        else:
            # Red light, must be on a safety island
            if pos in islands:
                next_last_move_dir = last_move_dir
                heapq.heappush(pq, (next_time, pos, next_time_mod, next_last_move_dir))

    return -1

print(solve())
