def is_increasing(mat, n, m):
    # Check if matrix is strictly increasing
    # Rows
    for i in range(n):
        for j in range(m-1):
            if mat[i][j] >= mat[i][j+1]:
                return False
    # Columns
    for j in range(m):
        for i in range(n-1):
            if mat[i][j] >= mat[i+1][j]:
                return False
    return True

n, m = map(int, input().split())

# Read first matrix
a = []
for _ in range(n):
    a.append(list(map(int, input().split())))

# Read second matrix
b = []
for _ in range(n):
    b.append(list(map(int, input().split())))

# Sort each row of both matrices independently
for i in range(n):
    row_a = a[i]
    row_b = b[i]
    # Sort values in row from both matrices
    combined = sorted(row_a + row_b)
    # Assign sorted values back to matrices
    a[i] = combined[:m]
    b[i] = combined[m:]

# Check if both matrices are strictly increasing
if is_increasing(a, n, m) and is_increasing(b, n, m):
    print("Possible")
else:
    print("Impossible")
