import sys

def can_cut_sheets(w, h):
    count = 1

    # While we can cut (at least one dimension even)
    while w % 2 == 0 or h % 2 == 0:
        if w % 2 == 0 and h % 2 == 0:
            # Both even, cut the smaller dimension
            if w <= h:
                w //= 2
            else:
                h //= 2
        elif w % 2 == 0:
            # Only w even, cut w
            w //= 2
        else:
            # Only h even, cut h
            h //= 2

        # After cutting, we double the number of sheets
        count *= 2

    return count

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        w, h, n = map(int, sys.stdin.readline().split())
        max_sheets = can_cut_sheets(w, h)
        if max_sheets >= n:
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    solve()
