            tokens.append('(')
            i += 1
        elif expr[i] == ')':
            tokens.append(')')
            i += 1

    output = []
    op_stack = []
    for token in tokens:
        if isinstance(token, int):
            output.append(token)
        elif token == '(':
            op_stack.append(token)
        elif token == ')':
            while op_stack and op_stack[-1] != '(':
                output.append(op_stack.pop())
            op_stack.pop()  # Remove the '('
