        elif s[pos] == '(':
            tokens.append((1, '('))
            pos += 1
        elif s[pos] == ')':
            tokens.append((1, ')'))
            pos += 1

    # Stack-based evaluation
    op_stack = []
    out_stack = []
    for token in tokens:
        if token[1] == '(':
            op_stack.append(token)
        elif token[1] == ')':
            while op_stack and op_stack[-1] != '(':
                out_stack.append(op_stack.pop())
