                op_stack.pop()  # Remove '('
            else:
                return None, pos - i  # Invalid
        elif token[1] in '+*':
            while op_stack and op_stack[-1] != '(' and (op_stack[-1] == '+' and token[1] == '*'):  # Higher precedence
                out_stack.append(op_stack.pop())
