# Compute square-free part of each number
def square_free_part(x):
    if x == 0:
        return 0
    result = 1
    x = abs(x)
    # Remove squares
    for i in range(2, int(x**0.5) + 1):
        count = 0
        while x % i == 0:
            count += 1
            x //= i
        if count % 2 == 1:
            result *= i
    if x > 1:
        result *= x
    return result

sf_parts = [square_free_part(num) for num in a]

# Count subarrays by number of distinct square-free parts
distinct_count = 0
counts = {}
result = [0] * (n + 1)  # result[k] = number of subarrays with exactly k distinct

# For each subarray, we can use the sliding window approach:
# Maintain a window [l, r] and expand to the right
for l in range(n):
    distinct_count = 0
    counts = {}
    for r in range(l, n):
        sf = sf_parts[r]
        if sf not in counts or counts[sf] == 0:
            distinct_count += 1
        counts[sf] = counts.get(sf, 0) + 1
        result[distinct_count] += 1

# Output result[1] to result[n]
print(' '.join(str(result[k]) for k in range(1, n + 1)))
