import sys
import bisect

def main():
    data = sys.stdin.buffer.read().splitlines()
    if not data:
        return

    n = int(data[0].decode())
    strings = []
    idx = 1
    for i in range(n):
        strings.append(data[i+1].decode())

    substrings_to_indices = {}

    for i, s in enumerate(strings):
        for j in range(len(s)):
            for k in range(j+1, len(s)+1):
                substr = s[j:k]
                if substr in substrings_to_indices:
                    substrings_to_indices[substr].append(i+1)
                else:
                    substrings_to_indices[substr] = [i+1]

    for key in substrings_to_indices:
        substrings_to_indices[key].sort()

    Q = int(data[n+1].decode())
    idx = n+2

    results = []
    for _ in range(Q):
        L = int(data[idx].decode())
        R = int(data[idx+1].decode())
        substr = data[idx+2].decode()
        idx += 3

        if substr not in substrings_to_indices:
            results.append("0")
        else:
            indices = substrings_to_indices[substr]
            left = bisect.bisect_left(indices, L)
            right = bisect.bisect_right(indices, R)
            results.append(str(right - left) + " ")

    sys.stdout.write("\n".join(results))

def run():
    main()

if __name__ == "__main__":
    run()

