def solve():
    import sys
    data = sys.stdin.read().strip().split()
    idx = 0

    while idx < len(data):
        m = int(data[idx])
        n = int(data[idx+1])
        idx += 2

        if m == 0 and n == 0:
            break

        # Read the grid with 1-indexed coordinates
        grid = [[0] * (m + 1) for _ in range(n + 1)]  # 1-indexed
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                grid[i][j] = int(data[idx])
                idx += 1

        # Find the maximum number of cells that can be visited
        max_visited = 0

        # Try all cells as starting points
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if grid[i][j] == 1:
                    # DFS with backtracking
                    visited = [[False] * (m + 1) for _ in range(n + 1)]
                    visited[i][j] = True

                    def dfs(x, y, count):
                        nonlocal max_visited
                        max_visited = max(max_visited, count)

                        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                            nx, ny = x + dx, y + dy

                            # Check bounds
                            if 1 <= nx <= n and 1 <= ny <= m and grid[nx][ny] == 1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                dfs(nx, ny, count + 1)
                                visited[nx][ny] = False

                    dfs(i, j, 1)

        print(max_visited)

solve()
