            if depth not in depth_lines:
                depth_lines[depth] = []
            depth_lines[depth].append(i)

        # Format each line
        for i, line in enumerate(lines):
            if i == 0:
                continue

            depth = line.count('.')
            text = line[depth:]

            if depth == 0:
                result.append(text)
                continue

            # Check if there are lines at the same depth before this one
            if depth in depth_lines and i > 0 and depth_lines[depth][0] < i:
                result.append(f"| +{text}")
            else:
                result.append(f" +{text}")

        print('\n'.join(result))

