q = int(input())

# Parse the compressed string
char_count = {}
i = 0
while i < len(compressed):
    if compressed[i].isalpha():
        char = compressed[i]
        # Get the number (can have leading zeros)
        num_str = ''
        while i + 1 < len(compressed) and compressed[i + 1].isdigit():
            num_str += compressed[i + 1]
            i += 1
        # If no digit after character, we have a problem
        if not num_str:
            num_str = '1'  # default to 1 if no number specified (though this shouldn't happen)
        char_count[char] = char_count.get(char, 0) + int(num_str)
        i += 1
    else:
        # Skip if we encounter a digit (shouldn't happen)
        i += 1

# Sort by character
sorted_chars = sorted(char_count.items())

# Compute prefix sums
prefix = [0]
for char, count in sorted_chars:
    prefix.append(prefix[-1] + count)

# Process queries
for _ in range(q):
    k = int(input())
    if k < 1 or k > prefix[-1]:
        print(-1)
    else:
        # Find which character's range includes k
        left, right = 0, len(prefix) - 1
        while left <= right:
            mid = (left + right) // 2
            if prefix[mid] < k <= prefix[mid + 1]:
                print(sorted_chars[mid][0])
                break
            elif prefix[mid] >= k:
                right = mid - 1
            else:
                left = mid + 1
